'use strict';

// MODULES //

var rfftf = require( './rfftf.js' );


// MAIN //

/**
* Performs the quarter-wave cosine forward transform.
*
* @private
* @param {number} n - length of the sequence to transform
* @param {Float64Array} x - input array containing sequence to be transformed
* @param {Float64Array} w - working array containing precomputed cosine values
* @param {Float64Array} xh - auxiliary working array
* @returns {void}
*/
function cosqf1( n, x, w, xh ) {
	var xim1;
	var modn;
	var np2;
	var ns2;
	var kc;
	var k;
	var i;

	// Function Body:
	ns2 = ( n + 1 ) / 2;
	np2 = n + 2;
	for ( k = 2; k <= ns2; k++ ) {
		kc = np2 - k;
		xh[ k - 1 ] = x[ k - 1 ] + x[ kc - 1 ];
		xh[ kc - 1 ] = x[ k - 1 ] - x[ kc - 1 ];
	}
	modn = n % 2;
	if ( modn === 0 ) {
		xh[ ns2 + 1 - 1 ] = x[ ns2 + 1 - 1 ] + x[ ns2 + 1 - 1 ];
	}
	for ( k = 2; k <= ns2; k++ ) {
		kc = np2 - k;
		x[ k - 1 ] = ( w[ k - 1 - 1 ] * xh[ kc - 1 ] ) + ( w[ kc - 1 - 1 ] * xh[ k - 1 ] );
		x[ kc - 1 ] = ( w[ k - 1 - 1 ] * xh[ k - 1 ] ) - ( w[ kc - 1 - 1 ] * xh[ kc - 1 ] );
	}
	if ( modn === 0 ) {
		x[ ns2 + 1 - 1 ] = w[ ns2 - 1 ] * xh[ ns2 + 1 - 1 ];
	}
	rfftf( n, x[ 1 - 1 ], xh[ 1 - 1 ] );
	for ( i = 3; i <= n; i += 2 ) {
		xim1 = x[ i - 1 - 1 ] - x[ i - 1 ];
		x[ i - 1 ] = x[ i - 1 - 1 ] + x[ i - 1 ];
		x[ i - 1 - 1 ] = xim1;
	}
}


// EXPORTS //

module.exports = cosqf1;
